<?php require_once __DIR__.'/includes/bootstrap.php';$publicTitle='Contact CuePOS | Request a Snooker Club Software Demo';$publicDescription='Contact CuePOS to request a demonstration or ask a question about snooker club management software.';$publicCanonical=siteUrl('/contact.php');$success='';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrf();$name=sanitize($_POST['name']??'');$email=filter_var($_POST['email']??'',FILTER_VALIDATE_EMAIL);$club=sanitize($_POST['club_name']??'');$message=sanitize($_POST['message']??'');if(!$name||!$email||!$club){$error='Please complete your name, business email and club name.';}else{try{$q=getDB()->prepare("INSERT INTO demo_requests(name,email,club_name,country_code,message,status) VALUES(?,?,?,?,?,'new')");$q->execute([$name,$email,$club,strtoupper(substr(sanitize($_POST['country_code']??''),0,2)),$message]);$success='Thanks — your request has been received. We will follow up through your business email.';}catch(Throwable $e){$error='Your request could not be saved yet. Please try again after the SaaS migration is installed.';}}}require __DIR__.'/includes/public-header.php'; ?><main class="max-w-4xl mx-auto px-5 py-20"><span class="eyebrow">Talk to CuePOS</span><h1 class="font-display text-5xl font-extrabold mt-5">See CuePOS in your club context.</h1><p class="text-slate-600 text-lg mt-5 max-w-2xl">Tell us about your club and we will prepare the right walkthrough for your tables, rates, players and staff workflow.</p><?php if($success): ?><div class="mt-7 p-4 rounded-xl bg-emerald-50 text-emerald-800 border border-emerald-200"><?=sanitize($success)?></div><?php endif; ?><?php if($error): ?><div class="mt-7 p-4 rounded-xl bg-red-50 text-red-800 border border-red-200"><?=sanitize($error)?></div><?php endif; ?><form method="post" class="mt-8 bg-white p-7 rounded-3xl border border-slate-200 grid md:grid-cols-2 gap-5"><input type="hidden" name="csrf_token" value="<?=csrfToken()?>"><label><span class="label text-slate-600">Your name</span><input required class="input bg-white" name="name"></label><label><span class="label text-slate-600">Business email</span><input required class="input bg-white" type="email" name="email"></label><label><span class="label text-slate-600">Club name</span><input required class="input bg-white" name="club_name"></label><label><span class="label text-slate-600">Country code</span><input class="input bg-white" maxlength="2" name="country_code" placeholder="PK"></label><label class="md:col-span-2"><span class="label text-slate-600">What would you like to improve?</span><textarea class="input bg-white min-h-28" name="message" placeholder="For example: 12 tables, café, two shifts and loyalty members."></textarea></label><div class="md:col-span-2"><button class="rounded-full bg-ink text-white px-6 py-3.5 font-bold">Request a demo</button></div></form></main><?php require __DIR__.'/includes/public-footer.php'; ?>
